<template><div><div class="page-head"><div><span>PHM Simulation Dataset</span><h2>故障诊断仿真数据集</h2><p>正常 baseline 与故障/退化数据统一目录，数据从 ZIP 流式读取。</p></div><el-tag type="success" effect="plain">已接入</el-tag></div><div class="metrics"><el-card><small>故障场景</small><strong>{{summary.categories?.length||0}}</strong><span>含正常基线</span></el-card><el-card><small>CSV 文件</small><strong>{{summary.csv_files||0}}</strong><span>原始/派生参数成对</span></el-card><el-card><small>样本组</small><strong>{{summary.sample_pairs||0}}</strong><span>按飞行次数及注入时刻</span></el-card><el-card><small>压缩包</small><strong>{{summary.archive_size_mb||0}}</strong><span>MB · 不重复解压</span></el-card></div><div class="workspace"><el-card class="catalog" shadow="never"><template #header><b>场景目录</b></template><div v-for="c in summary.categories" :key="c.key" :class="['category',{active:selected?.key===c.key}]" @click="select(c)"><i :class="c.kind"></i><div><b>{{c.name}}</b><span>{{c.key}} · {{c.raw_files}} 组</span></div><el-tag size="small" :type="c.kind==='baseline'?'success':'warning'">{{c.kind==='baseline'?'正常':'故障/退化'}}</el-tag></div></el-card><el-card class="files" shadow="never"><template #header><div class="file-head"><div><b>{{selected?.name||'请选择场景'}}</b><small v-if="selected">飞行次数 {{selected.flight_counts?.join(', ')}}；注入时刻 {{selected.injection_times?.join(', ')||'无'}}</small></div><el-input v-model="keyword" clearable placeholder="筛选文件名" style="width:220px"/></div></template><el-table :data="filtered" height="520" @row-click="preview"><el-table-column prop="name" label="文件" min-width="190"/><el-table-column prop="flight_count" label="飞行次数" width="90"/><el-table-column prop="injection_time" label="注入时刻" width="90"><template #default="s">{{s.row.injection_time??'—'}}</template></el-table-column><el-table-column label="数据类型" width="120"><template #default="s"><el-tag size="small" :type="s.row.data_type==='raw_state'?'primary':'info'">{{s.row.data_type==='raw_state'?'原始状态量':'派生参数'}}</el-tag></template></el-table-column><el-table-column prop="size_mb" label="MB" width="70"/></el-table></el-card></div><el-drawer v-model="drawer" title="数据抽样预览" size="75%"><el-alert type="info" :closable="false" :title="previewData.member"/><el-table :data="previewRows" height="600" size="small"><el-table-column v-for="col in previewColumns" :key="col" :prop="col" :label="col" width="120"/></el-table></el-drawer></div></template>
<script setup>import{ref,computed,onMounted}from'vue';const summary=ref({categories:[]}),selected=ref(null),files=ref([]),keyword=ref(''),drawer=ref(false),previewData=ref({});onMounted(async()=>{summary.value=await(await fetch('/api/v1/simulation-dataset/catalog/')).json();if(summary.value.categories?.length)select(summary.value.categories[0])});async function select(c){selected.value=c;files.value=(await(await fetch(`/api/v1/simulation-dataset/files/${c.key}/`)).json()).results||[]}const filtered=computed(()=>files.value.filter(x=>x.name.toLowerCase().includes(keyword.value.toLowerCase())));async function preview(row){previewData.value=await(await fetch(`/api/v1/simulation-dataset/preview/?limit=30&member=${encodeURIComponent(row.member)}`)).json();drawer.value=true}const previewColumns=computed(()=>previewData.value.columns||[]);const previewRows=computed(()=>(previewData.value.rows||[]).map(row=>Object.fromEntries(previewColumns.value.map((c,i)=>[c,row[i]]))));</script>
<style scoped>.page-head{display:flex;justify-content:space-between;align-items:end;margin-bottom:18px}.page-head span{font-size:11px;color:#2c82e7;font-weight:700}.page-head h2{margin:7px 0}.page-head p{margin:0;color:#8391a5}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-bottom:16px}.metrics small,.metrics strong,.metrics span{display:block}.metrics small,.metrics span{color:#8795a8;font-size:12px}.metrics strong{font-size:26px;margin:7px 0;color:#1d73cf}.workspace{display:grid;grid-template-columns:310px 1fr;gap:16px}.el-card{border-radius:11px}.category{display:flex;align-items:center;gap:10px;padding:11px;border-radius:8px;cursor:pointer;margin-bottom:4px}.category:hover,.category.active{background:#edf5ff}.category i{width:7px;height:34px;border-radius:5px;background:#ee9a36}.category i.baseline{background:#26af83}.category div{flex:1}.category b,.category span{display:block}.category span{font-size:11px;color:#8c99a9;margin-top:3px}.file-head{display:flex;align-items:center;justify-content:space-between}.file-head small{display:block;color:#8d99a9;margin-top:5px}@media(max-width:1150px){.workspace{grid-template-columns:1fr}.metrics{grid-template-columns:repeat(2,1fr)}}</style>
